import{_ as i,o as d,c as a,a3 as e}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语","description":"儒家四书之一：孔子与弟子的语录问答，二十篇，日用之中的德与学。","frontmatter":{"title":"论语","description":"儒家四书之一：孔子与弟子的语录问答，二十篇，日用之中的德与学。","category":"guide","aliases":["论语","lunyu","论语译注","论语篇章","论语目录"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/index.md","filePath":"lizhimingde/sishu-wujing/lunyu/index.md","lastUpdated":1790316338000}'),r={name:"lizhimingde/sishu-wujing/lunyu/index.md"};function l(n,t,h,s,g,u){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="论语" tabindex="-1">论语 <a class="header-anchor" href="#论语" aria-label="Permalink to &quot;论语&quot;">​</a></h1><p>《论语》不是一部「著作」，而是一部<strong>记录</strong>：孔子与弟子、时人的问答，被弟子与再传弟子分篇辑录。二十篇，约一万六千字，是中国最耐读的一部语录。</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><ul><li><strong>体例</strong>：语录体。多为短章，一章常只一两句；篇名取首章开头两三字（如「学而」取自「学而时习之」），<strong>篇名与内容并无主题关系</strong>。</li><li><strong>二十篇</strong>：学而、为政、八佾、里仁、公冶长、雍也、述而、泰伯、子罕、乡党、先进、颜渊、子路、宪问、卫灵公、季氏、阳货、微子、子张、尧曰。</li><li><strong>人物</strong>：孔子之外，出场最多的有颜回、子路、子贡、曾参、子夏、子张等，各人性格在问答里分明可见。</li></ul><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li><strong>它是中国人日常伦理的语法</strong>：「学而时习」「温故知新」「己所不欲，勿施于人」「君子不器」「三十而立」——数不清的成语语汇从这里出来。</li><li><strong>它教的不是体系，是判断</strong>：同一问题问不同弟子，孔子给的答案常常不同——因为他对人说话。</li><li><strong>它与道家形成对照</strong>：读《老子》看「无为」，读《论语》看「有为」如何在日用中落地。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>不必按主题分</strong>（篇名无主题），但可留意人物线索：跟着子路、子贡、颜回看孔子怎么因材施教。</li><li><strong>先从熟悉的篇章进</strong>：《学而》《为政》《里仁》《述而》《先进》几篇，是常被引用的核心。</li><li><strong>读法建议</strong>：一次读一小段，不必求快；遇到重复出现的词（仁、礼、君子、学、知、孝），可以停下来累积它在不同语境中的用法。</li><li><strong>注本</strong>：可参考杨伯峻《论语译注》（今人通行）、朱熹《四书章句集注》（理学视角）。</li></ol><h2 id="篇目" tabindex="-1">篇目 <a class="header-anchor" href="#篇目" aria-label="Permalink to &quot;篇目&quot;">​</a></h2><p>《论语》二十篇。篇名取自首章开头两三字，<strong>与内容无主题对应</strong>——这是语录体辑录的痕迹，读时不必强求篇名之意。</p><p>当前先把二十篇的篇名与路径立住，原文与逐篇解读按顺序分批推进。</p><h3 id="上论-前十篇" tabindex="-1">上论（前十篇） <a class="header-anchor" href="#上论-前十篇" aria-label="Permalink to &quot;上论（前十篇）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">序</th><th>篇</th><th>首章起句</th><th>入口</th></tr></thead><tbody><tr><td style="text-align:right;">01</td><td>学而</td><td>学而时习之</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-01">论语·学而</a></td></tr><tr><td style="text-align:right;">02</td><td>为政</td><td>为政以德</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-02">论语·为政</a></td></tr><tr><td style="text-align:right;">03</td><td>八佾</td><td>八佾舞于庭</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-03">论语·八佾</a></td></tr><tr><td style="text-align:right;">04</td><td>里仁</td><td>里仁为美</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-04">论语·里仁</a></td></tr><tr><td style="text-align:right;">05</td><td>公冶长</td><td>子谓公冶长</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-05">论语·公冶长</a></td></tr><tr><td style="text-align:right;">06</td><td>雍也</td><td>雍也可使南面</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-06">论语·雍也</a></td></tr><tr><td style="text-align:right;">07</td><td>述而</td><td>述而不作</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-07">论语·述而</a></td></tr><tr><td style="text-align:right;">08</td><td>泰伯</td><td>泰伯其可谓至德也已矣</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-08">论语·泰伯</a></td></tr><tr><td style="text-align:right;">09</td><td>子罕</td><td>子罕言利与命与仁</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-09">论语·子罕</a></td></tr><tr><td style="text-align:right;">10</td><td>乡党</td><td>孔子于乡党</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-10">论语·乡党</a></td></tr></tbody></table><h3 id="下论-后十篇" tabindex="-1">下论（后十篇） <a class="header-anchor" href="#下论-后十篇" aria-label="Permalink to &quot;下论（后十篇）&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">序</th><th>篇</th><th>首章起句</th><th>入口</th></tr></thead><tbody><tr><td style="text-align:right;">11</td><td>先进</td><td>先进于礼乐</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-11">论语·先进</a></td></tr><tr><td style="text-align:right;">12</td><td>颜渊</td><td>克己复礼为仁</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-12">论语·颜渊</a></td></tr><tr><td style="text-align:right;">13</td><td>子路</td><td>先之劳之</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-13">论语·子路</a></td></tr><tr><td style="text-align:right;">14</td><td>宪问</td><td>邦有道，谷</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-14">论语·宪问</a></td></tr><tr><td style="text-align:right;">15</td><td>卫灵公</td><td>卫灵公问陈于孔子</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-15">论语·卫灵公</a></td></tr><tr><td style="text-align:right;">16</td><td>季氏</td><td>季氏将伐颛臾</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-16">论语·季氏</a></td></tr><tr><td style="text-align:right;">17</td><td>阳货</td><td>阳货欲见孔子</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-17">论语·阳货</a></td></tr><tr><td style="text-align:right;">18</td><td>微子</td><td>微子去之</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-18">论语·微子</a></td></tr><tr><td style="text-align:right;">19</td><td>子张</td><td>士见危致命</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-19">论语·子张</a></td></tr><tr><td style="text-align:right;">20</td><td>尧曰</td><td>尧曰咨尔舜</td><td><a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-20">论语·尧曰</a></td></tr></tbody></table><h3 id="说明" tabindex="-1">说明 <a class="header-anchor" href="#说明" aria-label="Permalink to &quot;说明&quot;">​</a></h3><ul><li>「上论」「下论」只是传统的大致分法（前十篇与后十篇），不是内容界限。</li><li>篇名与首章起句的对应，是为了帮助定位；<strong>篇名本身不表主题</strong>。</li><li><strong>二十篇已全部落成</strong>（合计 512 章）：每篇均含原文（竹简／经典两种阅读）、注音字词卡片、<strong>逐段释义</strong>（经典阅读模式下点章节标题旁的 ▸ 展开）、三问解读（象／理／用）、现代重述与关联，体例统一。</li><li>原文依据通行本录入，<strong>保留原字</strong>（如「说」不改悦、「弟」不改悌、「孙」不改逊、「归」不改馈），通假与异文在各篇释义中说明；分章与用字以所用本子为准。</li><li><strong>「我的理解」各篇留空</strong>，待读者（或站主）精读后自行补写；释义词条亦以初次收录为主，后续精读时一并补全。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>入其门的次第：见<a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li></ul>',19)])])}const y=i(r,[["render",l]]);export{c as __pageData,y as default};
